/* @autogenerated */
import { ObservedSourceRepository } from 'app/features/observe/observed-source/repository/observed-source-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import {
  OBSERVED_ISSUE_EXCEL_COLUMNS,
  OBSERVED_ISSUE_EXCEL_SENSITIVE,
} from 'app/features/observe/observed-issue/model/observed-issue-excel-columns';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { ObservedIssue } from 'app/features/observe/observed-issue/model/observed-issue.model';
import { take, map } from 'rxjs';
import { ObservedIssueRepository } from 'app/features/observe/observed-issue/repository/observed-issue-repository.service';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'observed-issue-view-export-action',
  standalone: false,
  templateUrl: './observed-issue-view-export-action.component.html',
})
export class ObservedIssueViewExportActionComponent extends BaseExportAction<ObservedIssue> {
  protected readonly scope = 'observe/observed-issue';
  protected readonly repository = inject(ObservedIssueRepository);
  private readonly originRepository = inject(ObservedSourceRepository);

  readonly definition: ExportDefinition<ObservedIssue> = {
    name: 'observe.observed-issue',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: OBSERVED_ISSUE_EXCEL_COLUMNS,
    sensitive: OBSERVED_ISSUE_EXCEL_SENSITIVE,
    references: {
      origin: {
        names: (refs) =>
          this.originRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.code ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
